+pub(crate) fn emit_inverse<F: FnOnce(&mut B)>(b: &mut B, f: F) {
+    if b.count_only {
+        let snap = b.count_snapshot();
+        if b.fiat_hash.is_some() {
+            let hash_before = b.fiat_hash.clone();
+            b.count_only_capture_stack.push(Vec::new());
+            f(b);
+            let forward = b
+                .count_only_capture_stack
+                .pop()
+                .expect("count-only inverse capture stack");
+            b.restore_count_snapshot(snap);
+            b.fiat_hash = hash_before;
+            emit_inverse_ops_allowing_clean_resets(
+                b,
+                &forward,
+                "count-only hashed emit_inverse",
+            );
+            return;

+    if let Some((target, body_first)) = direct_target {
+        let lenders_ok = ladder_lenders.len() >= n - 2
+            && ladder_lenders.iter().all(|&l| {
+                !std::ptr::eq(l, target) && !c.iter().any(|&ci| std::ptr::eq(l, ci))
+            });
+        let target_ok = !c.iter().any(|&ci| std::ptr::eq(ci, target));
+        if n >= 3 && lenders_ok && target_ok {
+            let all_ctrls: Vec<&QReg> = c.to_vec();
+            let lenders: Vec<&QReg> = ladder_lenders[..n - 2].to_vec();
+            for i in 0..n_iters {
+                // `body_first` (reverse sweep) consumes the accumulator before
+                // this edge's toggle; otherwise (forward) toggle then consume.
+                if body_first {
+                    body(circ, i, target);
+                    mcx_dirty_ladder(circ, &all_ctrls, target, &lenders);
+                } else {
+                    mcx_dirty_ladder(circ, &all_ctrls, target, &lenders);
+                    body(circ, i, target);
+                }
+                if i + 1 < n_iters {
+                    let b = (i ^ (i + 1)).count_ones() as usize;
+                    for j in 0..b.min(n) {
+                        circ.x(c[j]);
+                    }
+                }
+            }
+            // restore c = v (same tail as the gate-mode path).
+            let last = n_iters - 1;
+            for (j, q) in c.iter().enumerate() {
+                if (last >> j) & 1 == 0 {
+                    circ.x(q);
+                }
+            }
+            return;
+        }

+pub fn mcx_dirty_ladder(
+    circ: &mut Circuit,
+    ctrls: &[&QReg],
+    target: &QReg,
+    dirty: &[&QReg],
+) {
+    let k = ctrls.len();
+    match k {
+        0 => {
+            circ.x(target);
+            return;
+        }
+        1 => {
+            circ.cx(ctrls[0], target);
+            return;
+        }
+        2 => {
+            circ.ccx(ctrls[0], ctrls[1], target);
+            return;
+        }
+        _ => {}
+    }
+
+    assert!(dirty.len() >= k - 2, "mcx_dirty_ladder lender shortage");
+    let dirty = &dirty[..k - 2];
+    for (index, &q) in dirty.iter().enumerate() {
+        assert!(!std::ptr::eq(q, target), "dirty lender aliases target");
+        assert!(
+            !ctrls.iter().any(|&control| std::ptr::eq(q, control)),
+            "dirty lender aliases control"
+        );
+        assert!(
+            !dirty[..index].iter().any(|&other| std::ptr::eq(q, other)),
+            "duplicate dirty lender"
+        );
+    }
+
+    let cascade = |circ: &mut Circuit, include_seed: bool| {
+        if include_seed {
+            circ.ccx(ctrls[0], ctrls[1], dirty[0]);
+        }
+        for i in 1..dirty.len() {
+            circ.ccx(dirty[i - 1], ctrls[i + 1], dirty[i]);
+        }
+        circ.ccx(dirty[dirty.len() - 1], ctrls[k - 1], target);
+        for i in (1..dirty.len()).rev() {
+            circ.ccx(dirty[i - 1], ctrls[i + 1], dirty[i]);
+        }
+        if include_seed {
+            circ.ccx(ctrls[0], ctrls[1], dirty[0]);
+        }
+    };
+
+    cascade(circ, true);
+    cascade(circ, false);
+}
